#[test]
fn run_command_lasm_backend_persists_user_store_when_db_base_flag_is_set() {
    let project_dir = temp_dir("sec4-run-command-lasm-db-persistence");
    let db_base = project_dir.join("lasm-db");
    let create_port = find_available_tcp_port();
    let create_duplicate_port = find_available_tcp_port();
    let list_port = find_available_tcp_port();
    let read_port = find_available_tcp_port();
    let read_by_email_port = find_available_tcp_port();
    let read_old_email_port = find_available_tcp_port();
    let update_port = find_available_tcp_port();
    let delete_port = find_available_tcp_port();
    let read_after_delete_port = find_available_tcp_port();
    fs::create_dir_all(project_dir.join("src")).expect("src directory should be created");
    fs::write(
        project_dir.join("sec4.toml"),
        r#"[package]
name = "runlasmdbpersistencecommand"
version = "0.1.0"

[build]
entry = "src/main.ut"
"#,
    )
    .expect("manifest should be written");
    fs::write(
        project_dir.join("src/main.ut"),
        r#"fn createUser() effects { net } -> Int {
  res.ok(201, "CreateUserResponse", 0);
  0
}

fn getUser() effects { net } -> Int {
  res.json(200, "UserResponse", 0);
  0
}

fn getUserByEmail() effects { net } -> Int {
  res.json(200, "UserByEmailResponse", 0);
  0
}

fn listUsers() effects { net } -> Int {
  res.json(200, "ListUsersResponse", 0);
  0
}

fn deleteUser() effects { net } -> Int {
  res.json(200, "DeleteUserResponse", 0);
  0
}

fn updateUser() effects { net } -> Int {
  res.json(200, "UpdateUserResponse", 0);
  0
}

fn main() effects { net } -> Int {
  let router = http.router();
  http.post(router, "/users", createUser);
  http.get(router, "/users", listUsers);
  http.get(router, "/users/:id", getUser);
  http.get(router, "/users/by-email", getUserByEmail);
  http.post(router, "/users/:id/update", updateUser);
  http.post(router, "/users/:id/delete", deleteUser);
  http.serve(8080, router);
  0
}
"#,
    )
    .expect("source should be written");

    let user_id = "123e4567-e89b-42d3-a456-426614174000";
    let create_payload = format!(
        "{{\"id\":\"{user_id}\",\"email\":\"user@example.com\",\"age\":30,\"tags\":[\"core\"],\"address\":{{\"zip\":\"12345\"}},\"meta\":{{\"flags\":{{\"a\":true,\"b\":false,\"c\":true}}}}}}"
    );
    let update_payload = format!(
        "{{\"id\":\"{user_id}\",\"email\":\"updated@example.com\",\"age\":31,\"tags\":[\"core\",\"updated\"],\"address\":{{\"zip\":\"67890\"}},\"meta\":{{\"flags\":{{\"a\":false,\"b\":true,\"c\":false}}}}}}"
    );

    let path = project_dir
        .to_str()
        .expect("project path should be valid utf-8");
    let db_base_value = db_base
        .to_str()
        .expect("db base path should be valid utf-8")
        .to_string();

    let run_lasm_oneshot_request = |port: u16, request: String| -> String {
        let port_value = port.to_string();
        let mut child = Command::new(cli_bin())
            .args([
                "run",
                "--path",
                path,
                "--backend",
                "lasm",
                "--db-base",
                db_base_value.as_str(),
                "--oneshot",
                "--port",
                port_value.as_str(),
                "--serve-timeout-ms",
                "20000",
            ])
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .expect("sec4 run command should start");

        let mut response = None;
        for _ in 0..800 {
            if let Some(status) = child
                .try_wait()
                .expect("run command wait should succeed while connecting")
            {
                panic!("run command exited before request with status: {status}");
            }

            match TcpStream::connect(("127.0.0.1", port)) {
                Ok(mut stream) => {
                    stream
                        .write_all(request.as_bytes())
                        .expect("request should be written");
                    let mut body = String::new();
                    stream
                        .read_to_string(&mut body)
                        .expect("response should be readable");
                    response = Some(body);
                    break;
                }
                Err(_) => thread::sleep(Duration::from_millis(25)),
            }
        }

        let response = match response {
            Some(response) => response,
            None => {
                let _ = child.kill();
                let _ = child.wait();
                panic!("run command LASM db persistence flow could not connect to server");
            }
        };

        let mut status = None;
        for _ in 0..240 {
            match child.try_wait().expect("run command wait should succeed") {
                Some(next) => {
                    status = Some(next);
                    break;
                }
                None => thread::sleep(Duration::from_millis(25)),
            }
        }
        let status = match status {
            Some(status) => status,
            None => {
                let _ = child.kill();
                let _ = child.wait();
                panic!("run command LASM db persistence process did not exit in expected window");
            }
        };
        assert!(
            status.success(),
            "run command LASM db persistence process should exit successfully"
        );
        response
    };

    let create_response = run_lasm_oneshot_request(
        create_port,
        format!(
            "POST /users HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            create_payload.len(),
            create_payload
        ),
    );
    assert!(
        create_response.contains("HTTP/1.1 201 Created"),
        "create response should contain deterministic 201 status:\n{create_response}"
    );
    assert!(
        create_response.contains("\"userId\":\"123e4567-e89b-42d3-a456-426614174000\""),
        "create response should include deterministic user id:\n{create_response}"
    );

    let duplicate_create_response = run_lasm_oneshot_request(
        create_duplicate_port,
        format!(
            "POST /users HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            create_payload.len(),
            create_payload
        ),
    );
    assert!(
        duplicate_create_response.contains("HTTP/1.1 409 Conflict"),
        "duplicate create response should contain deterministic 409 status:\n{duplicate_create_response}"
    );
    assert!(
        duplicate_create_response.contains("\"code\":\"HTTP.CONFLICT\""),
        "duplicate create response should include deterministic conflict code:\n{duplicate_create_response}"
    );

    let users_store_path = db_base.join("users.json");
    let persisted_store = fs::read_to_string(&users_store_path)
        .expect("LASM db persistence should write users store file");
    assert!(
        persisted_store.contains(user_id),
        "persisted users store should include created user id:\n{persisted_store}"
    );
    assert!(
        persisted_store.contains("\"email\": \"user@example.com\""),
        "persisted users store should include created user payload:\n{persisted_store}"
    );

    let list_response = run_lasm_oneshot_request(
        list_port,
        "GET /users HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n".to_string(),
    );
    assert!(
        list_response.contains("HTTP/1.1 200 OK"),
        "list response should contain deterministic 200 status:\n{list_response}"
    );
    assert!(
        list_response.contains("\"count\":1"),
        "list response should include deterministic count:\n{list_response}"
    );
    assert!(
        list_response.contains("\"id\":\"123e4567-e89b-42d3-a456-426614174000\""),
        "list response should include created user id:\n{list_response}"
    );

    let update_response = run_lasm_oneshot_request(
        update_port,
        format!(
            "POST /users/{user_id}/update HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            update_payload.len(),
            update_payload
        ),
    );
    assert!(
        update_response.contains("HTTP/1.1 200 OK"),
        "update response should contain deterministic 200 status:\n{update_response}"
    );
    assert!(
        update_response.contains("\"updated\":true"),
        "update response should include deterministic updated marker:\n{update_response}"
    );

    let persisted_store_after_update = fs::read_to_string(&users_store_path)
        .expect("LASM db persistence should keep users store after update");
    assert!(
        persisted_store_after_update.contains("\"email\": \"updated@example.com\""),
        "persisted users store should include updated user payload:\n{persisted_store_after_update}"
    );

    let read_response = run_lasm_oneshot_request(
        read_port,
        format!("GET /users/{user_id} HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n"),
    );
    assert!(
        read_response.contains("HTTP/1.1 200 OK"),
        "read response should contain deterministic 200 status:\n{read_response}"
    );
    assert!(
        read_response.contains("\"id\":\"123e4567-e89b-42d3-a456-426614174000\""),
        "read response should include persisted user id:\n{read_response}"
    );
    assert!(
        read_response.contains("\"email\":\"updated@example.com\""),
        "read response should include updated persisted user payload:\n{read_response}"
    );

    let read_by_email_response = run_lasm_oneshot_request(
        read_by_email_port,
        "GET /users/by-email?email=updated%40example.com HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n".to_string(),
    );
    assert!(
        read_by_email_response.contains("HTTP/1.1 200 OK"),
        "read-by-email response should contain deterministic 200 status:\n{read_by_email_response}"
    );
    assert!(
        read_by_email_response.contains("\"email\":\"updated@example.com\""),
        "read-by-email response should include updated persisted user payload:\n{read_by_email_response}"
    );

    let read_old_email_response = run_lasm_oneshot_request(
        read_old_email_port,
        "GET /users/by-email?email=user%40example.com HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n".to_string(),
    );
    assert!(
        read_old_email_response.contains("HTTP/1.1 404 Not Found"),
        "read-old-email response should contain deterministic 404 status:\n{read_old_email_response}"
    );
    assert!(
        read_old_email_response.contains("\"code\":\"HTTP.NOT_FOUND\""),
        "read-old-email response should include deterministic not-found error code:\n{read_old_email_response}"
    );

    let delete_response = run_lasm_oneshot_request(
        delete_port,
        format!(
            "POST /users/{user_id}/delete HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n"
        ),
    );
    assert!(
        delete_response.contains("HTTP/1.1 200 OK"),
        "delete response should contain deterministic 200 status:\n{delete_response}"
    );
    assert!(
        delete_response.contains("\"deleted\":true"),
        "delete response should include deterministic deleted marker:\n{delete_response}"
    );

    let persisted_store_after_delete = fs::read_to_string(&users_store_path)
        .expect("LASM db persistence should keep users store file after deletion");
    assert!(
        !persisted_store_after_delete.contains(user_id),
        "persisted users store should remove deleted user id:\n{persisted_store_after_delete}"
    );

    let read_after_delete_response = run_lasm_oneshot_request(
        read_after_delete_port,
        format!("GET /users/{user_id} HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n"),
    );
    assert!(
        read_after_delete_response.contains("HTTP/1.1 404 Not Found"),
        "read-after-delete response should contain deterministic 404 status:\n{read_after_delete_response}"
    );
    assert!(
        read_after_delete_response.contains("\"code\":\"HTTP.NOT_FOUND\""),
        "read-after-delete response should include deterministic not-found error code:\n{read_after_delete_response}"
    );

    fs::remove_dir_all(&project_dir).expect("temp project cleanup should succeed");
}

