    let port_value = port.to_string();
    let mut child = Command::new(cli_bin())
        .args([
            "run",
            "--path",
            &project_path,
            "--backend",
            "lasm",
            "--port",
            &port_value,
            "--instances",
            "2",
            "--autoscale-max-instances",
            "3",
            "--autoscale-check-ms",
            "100",
            "--cluster-status-json",
            &status_json_value,
            "--serve-timeout-ms",
            "20000",
            "--db-adapter",
            "sqlite",
            "--db-max-tx-handles",
            "32",
            "--db-records-max",
            "128",
            "--db-query-one-row-max-bytes",
            "4096",
            "--db-query-one-row-max-columns",
            "64",
            "--db-sql-template-max-bytes",
            "8192",
            "--db-params-max-bytes",
            "16384",
            "--db-params-max-entries",
            "99",
            "--db-op-sequence-max",
            "77",
            "--db-sqlite-busy-timeout-ms",
            "2500",
            "--db-sqlite-journal-mode",
            "wal",
            "--db-sqlite-synchronous",
            "normal",
            "--db-sqlite-lock-retry-max",
            "7",
            "--db-sqlite-lock-retry-delay-ms",
            "9",
        ])
        .env("SEC4_RT_LASM_CLUSTER_IDLE_SPIN_THRESHOLD", "41")
        .env("SEC4_RT_LASM_CLUSTER_IDLE_SLEEP_MICROS", "333")
        .env("SEC4_RT_LASM_CLUSTER_RELAY_BUFFER_BYTES", "16384")
        .env("SEC4_RT_LASM_CLUSTER_RELAY_IO_BURST_MAX", "11")
        .env("SEC4_RT_LASM_CLUSTER_RELAY_IDLE_BACKOFF_MAX", "5")
        .env("SEC4_RT_LASM_CLUSTER_RELAY_PUMP_SCAN_MULTIPLIER", "7")
        .env("SEC4_RT_LASM_CLUSTER_RELAY_BUFFER_POOL_MAX", "96")
        .env("SEC4_RT_LASM_CLUSTER_RELAY_BUFFER_POOL_PREWARM", "12")
        .env("SEC4_RT_LASM_CLUSTER_FALLBACK_CONNECT_MAX_ATTEMPTS", "13")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("sec4 run cluster status-json command should start");

    let mut status_json_seen = false;
    for _ in 0..800 {
        if let Some(status) = child
            .try_wait()
            .expect("run command wait should succeed while waiting for status json")
        {
            panic!("run cluster command exited before status json check with status: {status}");
        }
        if status_json_path.exists() {
            status_json_seen = true;
            break;
        }
        thread::sleep(Duration::from_millis(25));
    }
    assert!(
        status_json_seen,
        "cluster status json file should be created at {}",
        status_json_path.display()
    );

    thread::sleep(Duration::from_millis(300));
    let first_status_json = fs::read_to_string(&status_json_path)
        .expect("first status json snapshot should be readable");
    let first_status: serde_json::Value =
        serde_json::from_str(&first_status_json).expect("first status json should parse");
